'use strict';
/* Installable web app: offline cache (sw.js, generated by tools/build-site.js)
   and the "INSTALL APP" menu button. Does nothing on file:// or in the desktop app. */
const PWA = {
  prompt: null,

  init() {
    const web = /^https?:$/.test(location.protocol) && !window.hyperchaosDesktop;
    if (!web) return;
    if ('serviceWorker' in navigator) {
      window.addEventListener('load', () => {
        navigator.serviceWorker.register('sw.js').catch(() => { /* no sw.js in dev, fine */ });
      });
    }
    window.addEventListener('beforeinstallprompt', e => {
      e.preventDefault();
      this.prompt = e;
      this.showButton(true);
    });
    window.addEventListener('appinstalled', () => { this.prompt = null; this.showButton(false); });
  },

  showButton(on) {
    const b = document.getElementById('btnInstall');
    if (b) b.hidden = !on;
  },

  install() {
    if (!this.prompt) return;
    this.prompt.prompt();
    this.prompt.userChoice.finally(() => { this.prompt = null; this.showButton(false); });
  },
};
PWA.init();
